    id
    name
    definition
    refCount
    deprecated
    retired
    status
    grounding
    identityGap
    edgesOut {
      id
      fromTermId
      toTermId
      relType
      targetTerm {
        id
      }
    }
    tables(where: { domainId: { in: ["sales"] } }) {
      id
      tableName
      domainId
    }
    domains(where: { domainId: { in: ["sales","*"] } }) {
      domainId
    }
    refs(where: { domainId: { in: ["sales"] } }) {
      columnKey
      columnName
      tableId
      tableName
      domainId
      column {
        dataType
        description
        sensitivity {
          tags
        }
      }
      registeredTable {
        id
        sourceId
        description
        checkedBy {
          latestOutcome
          latestRunAt
        }
        product {
          id
        }
      }
    }
    experts {
      userId
      kind
    }
  }
}

